  // ctx
  'help.ctx.dashboard.title': 'Bảng điều khiển',
  'help.ctx.dashboard.summary':
    'Bảng điều khiển hiển thị tất cả chuyến đi của bạn. Thẻ trên cùng, thiết kế như thẻ lên máy bay, cho thấy chuyến đi đang diễn ra hoặc sắp tới. Hàng bên dưới thống kê những nơi bạn đã đi, và các thẻ liệt kê mọi chuyến đi bạn đang lên kế hoạch, đã lưu trữ hoặc đã hoàn thành.',
  'help.ctx.dashboard.bullet.1':
    'Thẻ lên máy bay: chuyến đi đang diễn ra hoặc sắp tới, kèm ngày, người đi cùng, địa điểm và đồng hồ đếm ngược. Nhấp vào thẻ để mở chuyến đi. Bốn nút ở góc trên bên phải để chỉnh sửa, nhân bản, lưu trữ hoặc xóa chuyến đi.',
  'help.ctx.dashboard.bullet.2':
    'Thống kê du lịch: số quốc gia đã đến, số chuyến đi, số ngày trên đường và quãng đường đã bay, tính trên tất cả chuyến đi của bạn.',
  'help.ctx.dashboard.bullet.3':
    'Thẻ chuyến đi, lọc theo “Đã lên kế hoạch”, “Đã lưu trữ” và “Hoàn thành”, dạng lưới hoặc danh sách. Ô tìm kiếm phía trên tìm trong tất cả chuyến đi cùng lúc, theo tiêu đề, ngày hoặc một địa điểm trong chuyến. Các nút chỉnh sửa, nhân bản, lưu trữ và xóa chuyến đi nằm ở góc trên bên phải ảnh của mỗi thẻ.',
  'help.ctx.dashboard.bullet.4':
    'Tiện ích bên phải: bộ đổi tiền tệ, “Bộ sưu tập” (khi tiện ích bổ sung Bộ sưu tập đang bật), đồng hồ thế giới, đặt chỗ sắp tới và tiện ích từ plugin. Các tiện ích có sẵn có thể tắt trong “Cài đặt”, “Giao diện”.',
  'help.ctx.dashboard.bullet.5': 'Thẻ “Chuyến đi mới” và nút ở góc dưới bên phải đều dùng để tạo chuyến đi mới.',

  // create-trip
  'help.guide.create-trip.title': 'Tạo chuyến đi',
  'help.guide.create-trip.goal': 'Bắt đầu một chuyến đi mới với tên, ngày và ảnh bìa.',
  'help.guide.create-trip.step.1':
    'Nhấn “Chuyến đi mới”. Thẻ ở cuối danh sách chuyến đi và nút ở góc dưới bên phải cũng làm đúng việc này.',
  'help.guide.create-trip.step.2':
    'Đặt tên cho chuyến đi. Đây là trường duy nhất bạn cần điền; mọi thứ khác có thể thêm sau.',
  'help.guide.create-trip.step.3':
    'Chọn ngày bắt đầu và ngày kết thúc. TREK tạo mỗi ngày một ngày trong kế hoạch, để bạn bắt đầu lên lịch trình. Chưa có ngày? Để trống cả hai và nhập “Số ngày”.',
  'help.guide.create-trip.step.4':
    'Không bắt buộc: thêm ảnh bìa. Bạn có thể tải ảnh của mình lên, kéo hoặc dán ảnh vào, hoặc tìm ảnh theo điểm đến trên Unsplash.',
  'help.guide.create-trip.step.5': 'Nhấn “Tạo chuyến đi mới”.',
  'help.guide.create-trip.result':
    'Chuyến đi xuất hiện trên bảng điều khiển. Nếu là chuyến đi tiếp theo của bạn, nó sẽ hiện trong thẻ lên máy bay ở trên cùng.',
  'help.guide.create-trip.tip.1':
    'Bạn có thể đổi ngày sau. Nếu chuyến đi đã có đặt chỗ, TREK sẽ hỏi bạn có muốn dời các đặt chỗ theo các ngày không.',
  'help.guide.create-trip.tip.2':
    'Tiền tệ chuyến đi bạn chọn ở đây là đơn vị mà mọi chi phí được quy đổi về. Hãy chọn tiền tệ của điểm đến.',

  // edit-trip
