  'help.guide.widgets.result': 'Khi bạn ẩn widget, các chuyến đi có thêm chỗ. Tắt cả cột bên phải để căn giữa bố cục.',
  'help.guide.widgets.link': 'Mở cài đặt giao diện',

  // currency-widget
  'help.guide.currency-widget.title': 'Đổi tiền tệ',
  'help.guide.currency-widget.goal': 'Quy đổi một số tiền giữa hai loại tiền tệ theo tỷ giá hiện tại.',
  'help.guide.currency-widget.step.1': 'Nhập số tiền và chọn hai loại tiền tệ.',
  'help.guide.currency-widget.step.2': 'Mũi tên ở giữa đổi chỗ hai loại tiền; mũi tên tròn làm mới tỷ giá.',
  'help.guide.currency-widget.result': 'Cặp tiền tệ của bạn được lưu theo tài khoản, nên giống nhau trên mọi thiết bị.',
