  // timezones-widget
  'help.guide.timezones-widget.title': 'Thêm đồng hồ thế giới',
  'help.guide.timezones-widget.goal': 'Xem giờ địa phương tại các điểm đến của bạn.',
  'help.guide.timezones-widget.step.1':
    'Bấm + trong tiện ích “Múi giờ”, tìm một thành phố, ví dụ Lisbon, và chọn từ danh sách.',
  'help.guide.timezones-widget.step.2': 'Để xóa một đồng hồ, rê chuột vào đó rồi nhấp dấu × hiện ra ở bên phải.',
  'help.guide.timezones-widget.result': 'Các đồng hồ của bạn được lưu cùng tài khoản.',
