  'help.guide.search-trips.step.1':
    'Gõ vào ô “Tìm chuyến đi hoặc địa điểm” phía trên các thẻ. Danh sách được lọc ngay khi bạn gõ, tìm cùng lúc trong các chuyến đi đã lên kế hoạch, đã lưu trữ và đã hoàn thành.',
